-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     REPORT_DATE,     CASE         WHEN SHIPMENT_STATUS = 'I'         THEN 'HELD IN INPUT - Shipment not yet confirmed shipped'         WHEN EST_ARR_DATE IS NULL         THEN 'NO ETA - Shipment en route with no expected arrival date'         WHEN EST_ARR_DATE &lt; TRUNC(SYSDATE)         THEN 'OVERDUE - Past expected arrival date'         WHEN EST_ARR_DATE = TRUNC(SYSDATE)         THEN 'DUE TODAY - Expected to arrive today'         WHEN DAYS_IN_TRANSIT &gt; 7         THEN 'IN TRANSIT EXTENDED - Over 7 days since shipment'         WHEN DAYS_IN_TRANSIT &gt; 3         THEN 'IN TRANSIT - 4 to 7 days in transit'         ELSE 'IN TRANSIT - Within normal transit time'     END                                                   AS HOLD_CLASSIFICATION,     CASE         WHEN SHIPMENT_STATUS = 'I' AND DAYS_IN_TRANSIT &gt; 3         THEN '1 - CRITICAL: Input status for over 3 days - confirm shipment'         WHEN EST_ARR_DATE IS NOT NULL              AND EST_ARR_DATE &lt; TRUNC(SYSDATE) - 2         THEN '2 - CRITICAL: Overdue by more than 2 days - chase supplier'         WHEN EST_ARR_DATE IS NOT NULL              AND EST_ARR_DATE &lt; TRUNC(SYSDATE)         THEN '3 - HIGH: Past estimated arrival date'         WHEN EST_ARR_DATE IS NULL AND DAYS_IN_TRANSIT &gt; 5         THEN '3 - HIGH: No ETA and in transit over 5 days'         WHEN DAYS_IN_TRANSIT &gt; 7         THEN '4 - MEDIUM: Extended transit time'         WHEN CATCH_WEIGHT_IND = 'Y' AND DAYS_IN_TRANSIT &gt; 3         THEN '3 - HIGH: Fresh catch weight item held over 3 days'         ELSE '5 - MONITOR'     END                                                   AS URGENCY,     SHIPMENT_NO,     SHIPMENT_STATUS,     CASE SHIPMENT_STATUS         WHEN 'I' THEN 'Input / In Progress'         WHEN 'S' THEN 'Shipped'         WHEN 'T' THEN 'In Transit'         WHEN 'R' THEN 'Received'         WHEN 'C' THEN 'Closed'         ELSE SHIPMENT_STATUS     END                                                   AS SHIPMENT_STATUS_DESC,     ASN_NUMBER,     FROM_LOCATION_ID,     FROM_LOC_TYPE,     SHIP_DATE,     EST_ARR_DATE,     DAYS_IN_TRANSIT,     CASE WHEN EST_ARR_DATE IS NOT NULL          THEN EST_ARR_DATE - TRUNC(SYSDATE)     END                                                   AS DAYS_UNTIL_ETA,     CASE WHEN EST_ARR_DATE IS NOT NULL               AND EST_ARR_DATE &lt; TRUNC(SYSDATE)          THEN TRUNC(SYSDATE) - EST_ARR_DATE     END                                                   AS DAYS_OVERDUE,     INVC_MATCH_STATUS,     CASE INVC_MATCH_STATUS         WHEN 'U' THEN 'Unmatched'         WHEN 'M' THEN 'Matched'         WHEN 'C' THEN 'Closed'         ELSE NVL(INVC_MATCH_STATUS, 'Not Set')     END                                                   AS INVC_MATCH_STATUS_DESC,     PO_NUMBER,     PO_STATUS,     CASE PO_STATUS         WHEN 'W' THEN 'Worksheet'  WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'   WHEN 'C' THEN 'Closed'         ELSE PO_STATUS     END                                                   AS PO_STATUS_DESC,     PO_WRITTEN_DATE,     NOT_BEFORE_DATE,     NOT_AFTER_DATE,     CURRENCY_CODE,     SUPPLIER_ID,     SUPPLIER_NAME,     SUPPLIER_STATUS,     ORIGIN_COUNTRY_ID,     DEST_LOCATION_ID,     DEST_LOC_TYPE,     CASE DEST_LOC_TYPE         WHEN 'S' THEN DEST_STORE_NAME         WHEN 'W' THEN DEST_WH_NAME         ELSE TO_CHAR(DEST_LOCATION_ID)     END                                                   AS DEST_LOCATION_NAME,     DEPT_NO,     DEPT_NAME,     CLASS_NO,     CLASS_NAME,     SUBCLASS_NO,     SUBCLASS_NAME,     ITEM_ID,     ITEM_DESCRIPTION,     UOM,     PACK_IND,     CATCH_WEIGHT_IND,     CASE CATCH_WEIGHT_IND         WHEN 'Y' THEN 'FRESH CATCH WEIGHT - Shelf life critical'         ELSE          'STANDARD'     END                                                   AS FRESH_ITEM_FLAG,     VPN,     QTY_ON_SHIPMENT,     QTY_RECEIVED_SO_FAR,     QTY_ON_SHIPMENT - QTY_RECEIVED_SO_FAR                AS QTY_STILL_HELD,     UNIT_COST,     ROUND(SHIPMENT_VALUE_RAW,   2)                        AS SHIPMENT_VALUE,     ROUND(OUTSTANDING_VALUE_RAW, 2)                       AS OUTSTANDING_HELD_VALUE,     CURRENT_SOH_AT_DEST,     SUPP_LEAD_TIME,     PICKUP_LEAD_TIME,     CASE         WHEN SHIPMENT_STATUS = 'I' AND DAYS_IN_TRANSIT &gt; 3         THEN 'Update shipment status to Shipped or confirm with supplier that goods have departed'         WHEN EST_ARR_DATE IS NOT NULL              AND EST_ARR_DATE &lt; TRUNC(SYSDATE) - 2         THEN 'URGENT: Contact carrier and supplier; check for delivery exception or customs hold'         WHEN EST_ARR_DATE IS NOT NULL              AND EST_ARR_DATE &lt; TRUNC(SYSDATE)         THEN 'Chase delivery: confirm with carrier; update ETA or initiate replacement order if fresh item'         WHEN EST_ARR_DATE IS NULL AND DAYS_IN_TRANSIT &gt; 5         THEN 'Set estimated arrival date on shipment; contact supplier for delivery confirmation'         WHEN CATCH_WEIGHT_IND = 'Y' AND DAYS_IN_TRANSIT &gt; 3         THEN 'Fresh catch weight item: contact supplier urgently; arrange replacement if needed'         WHEN DAYS_IN_TRANSIT &gt; 7         THEN 'Extended transit: investigate carrier delay; check if invclshp.pc will auto-close shipment'         ELSE 'Monitor - within normal transit window'     END                                                   AS RECOMMENDED_ACTION FROM (

