                            AS DEPT_NAME,         im.CLASS                                          AS CLASS_NO,         c.CLASS_NAME                                      AS CLASS_NAME,         im.SUBCLASS                                       AS SUBCLASS_NO,         sc.SUB_NAME                                       AS SUBCLASS_NAME,         ss.ITEM                                           AS ITEM_ID,         im.ITEM_DESC                                      AS ITEM_DESCRIPTION,         im.STANDARD_UOM                                   AS UOM,         im.PACK_IND                                       AS PACK_IND,         im.CATCH_WEIGHT_IND                               AS CATCH_WEIGHT_IND,         NVL(ss.QTY_EXPECTED,  0)                          AS QTY_ON_SHIPMENT,         NVL(ss.QTY_RECEIVED,  0)                          AS QTY_RECEIVED_SO_FAR,         NVL(ss.UNIT_COST,     0)                          AS UNIT_COST,         NVL(ss.QTY_EXPECTED, 0) * NVL(ss.UNIT_COST, 0)   AS SHIPMENT_VALUE_RAW,         (NVL(ss.QTY_EXPECTED, 0)          - NVL(ss.QTY_RECEIVED, 0)) * NVL(ss.UNIT_COST, 0)                                                           AS OUTSTANDING_VALUE_RAW,         NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH_AT_DEST,         NVL(isc.LEAD_TIME,      0)                        AS SUPP_LEAD_TIME,         NVL(isc.PICKUP_LEAD_TIME, 0)                      AS PICKUP_LEAD_TIME     FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_SHIPSKU              ss   ON  sh.SHIPMENT  = ss.SHIPMENT     JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO  = oh.ORDER_NO     LEFT JOIN MFCS_RDS.RDS_WV_ORDSKU           os   ON  oh.ORDER_NO  = os.ORDER_NO                                                     AND  ss.ITEM      = os.ITEM     JOIN (

