R_STATUS\",\"isUserCalculation\":false},{\"prepColumnName\":\"ORIGIN_COUNTRY_ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"DEST_LOCATION_ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"DEST_LOC_TYPE\",\"isUserCalculation\":false},{\"prepColumnName\":\"DEST_LOCATION_NAME\",\"isUserCalculation\":false},{\"prepColumnName\":\"DEPT_NO\",\"isUserCalculation\":false},{\"prepColumnName\":\"DEPT_NAME\",\"isUserCalculation\":false},{\"prepColumnName\":\"CLASS_NO\",\"isUserCalculation\":false},{\"prepColumnName\":\"CLASS_NAME\",\"isUserCalculation\":false},{\"prepColumnName\":\"SUBCLASS_NO\",\"isUserCalculation\":false},{\"prepColumnName\":\"SUBCLASS_NAME\",\"isUserCalculation\":false},{\"prepColumnName\":\"ITEM_ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"ITEM_DESCRIPTION\",\"isUserCalculation\":false},{\"prepColumnName\":\"UOM\",\"isUserCalculation\":false},{\"prepColumnName\":\"PACK_IND\",\"isUserCalculation\":false},{\"prepColumnName\":\"CATCH_WEIGHT_IND\",\"isUserCalculation\":false},{\"prepColumnName\":\"FRESH_ITEM_FLAG\",\"isUserCalculation\":false},{\"prepColumnName\":\"VPN\",\"isUserCalculation\":false},{\"prepColumnName\":\"QTY_ON_SHIPMENT\",\"isUserCalculation\":false},{\"prepColumnName\":\"QTY_RECEIVED_SO_FAR\",\"isUserCalculation\":false},{\"prepColumnName\":\"QTY_STILL_HELD\",\"isUserCalculation\":false},{\"prepColumnName\":\"UNIT_COST\",\"isUserCalculation\":false},{\"prepColumnName\":\"SHIPMENT_VALUE\",\"isUserCalculation\":false},{\"prepColumnName\":\"OUTSTANDING_HELD_VALUE\",\"isUserCalculation\":false},{\"prepColumnName\":\"CURRENT_SOH_AT_DEST\",\"isUserCalculation\":false},{\"prepColumnName\":\"SUPP_LEAD_TIME\",\"isUserCalculation\":false},{\"prepColumnName\":\"PICKUP_LEAD_TIME\",\"isUserCalculation\":false},{\"prepColumnName\":\"RECOMMENDED_ACTION\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"FROM_LOCATION_ID\"],\"expressionSourceColumns\":[\"FROM_LOCATION_ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"FROM_LOCATION_ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"FROM_LOCATION_ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"PO_NUMBER\"],\"expressionSourceColumns\":[\"PO_NUMBER\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"PO_NUMBER\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"PO_NUMBER\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"SUPPLIER_ID\"],\"expressionSourceColumns\":[\"SUPPLIER_ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"SUPPLIER_ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"SUPPLIER_ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"DEPT_NO\"],\"expressionSourceColumns\":[\"DEPT_NO\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"DEPT_NO\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"DEPT_NO\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"DEST_LOCATION_ID\"],\"expressionSourceColumns\":[\"DEST_LOCATION_ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"DEST_LOCATION_ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"DEST_LOCATION_ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        sh.SHIPMENT                                       AS SHIPMENT_NO,\\n        sh.STATUS_CODE                                    AS SHIPMENT_STATUS,\\n        sh.ASN                                            AS ASN_NUMBER,\\n        sh.FROM_LOC                                       AS FROM_LOCATION_ID,\\n        sh.FROM_LOC_TYPE                                  AS FROM_LOC_TYPE,\\n        sh.SHIP_DATE                                      AS SHIP_DATE,\\n        sh.EST_ARR_DATE                                   AS EST_ARR_DATE,\\n        TRUNC(SYSDATE) - TRUNC(sh.SHIP_DATE)             AS DAYS_IN_TRANSIT,\\n        sh.INVC_MATCH_STATUS                              AS INVC_MATCH_STATUS,\\n        sh.ORDER_NO                                       AS PO_NUMBER,\\n        oh.STATUS                                         AS PO_STATUS,\\n        oh.WRITTEN_DATE                                   AS PO_WRITTEN_DATE,\\n        oh.NOT_BEFORE_DATE                                AS NOT_BEFORE_DATE,\\n        oh.NOT_AFTER_DATE                                 AS NOT_AFTER_DATE,\\n        oh.CURRENCY_CODE                                  AS CURRENCY_CODE,\\n        oh.SUPPLIER                                       AS SUPPLIER_ID,\\n        sp.SUP_NAME                                       AS SUPPLIER_NAME,\\n        sp.SUP_STATUS                                     AS SUPPLIER_STATUS,\\n        os.ORIGIN_COUNTRY_ID                              AS ORIGIN_COUNTRY_ID,\\n        os.REF_ITEM                                       AS VPN,\\n        sh.TO_LOC                                         AS DEST_LOCATION_ID,\\n        sh.TO_LOC_TYPE                                    AS DEST_LOC_TYPE,\\n        st.STORE_NAME                                     AS DEST_STORE_NAME,\\n        wh.WH_NAME                                        AS DEST_WH_NAME,\\n        im.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        im.CLASS                                          AS CLASS_NO,\\n        c.CLASS_NAME                                      AS CLASS_NAME,\\n        im.SUBCLASS                                       AS SUBCLASS_NO,\\n        sc.SUB_NAME                                       AS SUBCLASS_NAME,\\n        ss.ITEM                                           AS ITEM_ID,\\n        im.ITEM_DESC                                      AS ITEM_DESCRIPTION,\\n        im.STANDARD_UOM                                   AS UOM,\\n        im.PACK_IND                                       AS PACK_IND,\\n        im.CATCH_WEIGHT_IND                               AS CATCH_WEIGHT_IND,\\n        NVL(ss.QTY_EXPECTED,  0)                          AS QTY_ON_SHIPMENT,\\n        NVL(ss.QTY_RECEIVED,  0)                          AS QTY_RECEIVED_SO_FAR,\\n        NVL(ss.UNIT_COST,     0)                          AS UNIT_COST,\\n        NVL(ss.QTY_EXPECTED, 0) * NVL(ss.UNIT_COST, 0)   AS SHIPMENT_VALUE_RAW,\\n        (NVL(ss.QTY_EXPECTED, 0)\\n         - NVL(ss.QTY_RECEIVED, 0)) * NVL(ss.UNIT_COST, 0)\\n                                                          AS OUTSTANDING_VALUE_RAW,\\n        NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH_AT_DEST,\\n        NVL(isc.LEAD_TIME,      0)                        AS SUPP_LEAD_TIME,\\n        NVL(isc.PICKUP_LEAD_TIME, 0)                      AS PICKUP_LEAD_TIME\\n    FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh\\n    JOIN  MFCS_RDS.RDS_WV_SHIPSKU              ss   ON  sh.SHIPMENT  = ss.SHIPMENT\\n    JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO  = oh.ORDER_NO\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDSKU           os   ON  oh.ORDER_NO  = os.ORDER_NO\\n                                                    AND  ss.ITEM      = os.ITEM\\n    JOIN (\\n

-- ── Query 6 ────────────────────────────────────────────────────────────
SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS,\\n               STATUS, STANDARD_UOM, PACK_IND, CATCH_WEIGHT_IND\\n        FROM   MFCS_RDS.RDS_WV_ITEM_MASTER\\n        WHERE  TRAN_LEVEL = ITEM_LEVEL\\n    )                                          im   ON  ss.ITEM      = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  im.DEPT      = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                c    ON  im.DEPT      = c.DEPT\\n                                                    AND  im.CLASS     = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc   ON  im.DEPT      = sc.DEPT\\n                                                    AND  im.CLASS     = sc.CLASS\\n                                                    AND  im.SUBCLASS  = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp   ON  oh.SUPPLIER  = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE            st   ON  sh.TO_LOC    = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH               wh   ON  sh.TO_LOC    = wh.WH\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils  ON  ss.ITEM      = ils.ITEM\\n                                                    AND  sh.TO_LOC    = ils.LOC\\n                                                    AND  sh.TO_LOC_TYPE = ils.LOC_TYPE\\n    LEFT JOIN (\\n

-- ── Query 7 ────────────────────────────────────────────────────────────
SELECT ITEM, SUPPLIER, LEAD_TIME, PICKUP_LEAD_TIME\\n        FROM   MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY\\n        WHERE  PRIMARY_SUPP_IND    = 'Y'\\n        AND    PRIMARY_COUNTRY_IND = 'Y'\\n    )                                          isc  ON  ss.ITEM      = isc.ITEM\\n                                                    AND  oh.SUPPLIER  = isc.SUPPLIER\\n    WHERE\\n        sh.STATUS_CODE IN ('S','T','I')\\n        AND sh.SHIP_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n)\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-03T05:36:46.192+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_204_Fresh_Receipts_Held'","parent-namespace":"ReCommon","parent-name":"RPT_204_Fresh_Receipts_Held","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_204_Fresh_Receipts_Held'"}
